class SimpleConnectionPool {
  Queue<Connection> available = new LinkedList<>();
  Connection borrow() { return available.poll(); }
  void giveBack(Connection c) { available.offer(c); }
}
// 5x: borrow() -> uzyj -> giveBack() - sekwencyjnie reuzywajac te same 3 polaczenia

